-- A small clinic's legacy schema, standing in for a pg_dump capture.

CREATE SCHEMA IF NOT EXISTS clinic;

CREATE TYPE clinic.visit_kind AS ENUM ('checkup', 'urgent', 'follow_up');

CREATE DOMAIN clinic.postcode AS text CHECK (VALUE ~ '^[A-Z0-9 ]+$');

CREATE TABLE clinic.patients (
    id bigserial PRIMARY KEY,
    email clinic.citext NOT NULL,
    full_name text NOT NULL,
    status text DEFAULT 'active' NOT NULL
        CONSTRAINT patients_status_check CHECK (status IN ('active', 'archived')),
    postcode clinic.postcode,
    tags text[],
    password_digest text,
    location point,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);

CREATE UNIQUE INDEX patients_email_index ON clinic.patients (email);

CREATE UNIQUE INDEX patients_active_name_index ON clinic.patients (full_name) WHERE status = 'active';

CREATE TABLE clinic.visits (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patient_id bigint NOT NULL REFERENCES clinic.patients (id) ON DELETE CASCADE,
    kind clinic.visit_kind NOT NULL,
    notes text,
    "Room" text
);
